sp_widget.client_script:
api.controller=function($scope){
    var c=this;
    c.filtered=angular.copy(c.data.departments||[]);

    $scope.$watch(
        function(){
            return $scope.page.deptSearch;
        },
        function(text){
            var search=(text||'').toLowerCase();
            if(!search){
                c.filtered=angular.copy(c.data.departments||[]);
            } else {
                c.filtered=c.data.departments.filter(function(dept){
                    return (dept.name||'').toLowerCase().indexOf(search)>-1 ||
                           (dept.description||'').toLowerCase().indexOf(search)>-1;
                });
            }
        }
    );
};

sp_widget.css:
/* ===========================
   DEPARTMENT GRID
=========================== */

.department-grid{

margin-top:20px;

display:grid;

grid-template-columns:
repeat(
auto-fit,
minmax(
280px,
1fr
)
);

gap:20px;

align-items:stretch;

}



/* ===========================
   CARD
=========================== */

.department-card{

background:#FFFFFF;

border-radius:30px;
border: 1px solid grey;
padding:30px;

min-height:360px;

display:flex;

flex-direction:column;

position:relative;

overflow:hidden;

box-shadow:
0 18px 42px
rgba(
8,
24,
74,
.06
);

transition:
transform .25s,
box-shadow .25s;

}


.department-card:hover{

transform:
translateY(-6px);

box-shadow:
0 24px 52px
rgba(
8,
24,
74,
.10
);

}


/* decorative */

.department-card:after{

content:"";

position:absolute;

right:-70px;

bottom:-70px;

width:180px;

height:180px;

border-radius:50%;

background:
linear-gradient(
135deg,
#24D3A1,
#47D8C6
);

opacity:.06;

}



/* ===========================
   ICON
=========================== */

.dept-icon{

width:72px;

height:72px;

border-radius:22px;

background:
linear-gradient(
135deg,
#24D3A1,
#47D8C6
);

display:flex;

align-items:center;

justify-content:center;

font-size:32px;

position:relative;

z-index:2;

}



/* ===========================
   NAME
=========================== */

.dept-name{

margin-top:24px;

font-size:25px;

font-weight:800;

color:#07195A;

line-height:1.2;

position:relative;

z-index:2;

word-break:break-word;

}



/* ===========================
   COUNT
=========================== */

.dept-count{

margin-top:14px;

font-size:15px;

font-weight:700;

color:#2F62F5;

position:relative;

z-index:2;

}



/* ===========================
   DESCRIPTION
=========================== */

.dept-desc{

margin-top:18px;

font-size:14px;

line-height:1.8;

color:#7081A6;

flex:1;

position:relative;

z-index:2;

}



/* ===========================
   BUTTON
=========================== */

.dept-btn{

margin-top:28px;

height:58px;

display:flex;

align-items:center;

justify-content:center;

border-radius:18px;

background:
linear-gradient(
90deg,
#24D3A1,
#41D4C5
);

color:white !important;

font-size:15px;

font-weight:700;

text-decoration:none !important;

transition:.25s;

position:relative;

z-index:2;

}


.dept-btn:hover{

transform:
translateY(-2px);

box-shadow:
0 14px 28px
rgba(
36,
211,
161,
.25
);

}



/* ===========================
   EMPTY STATE
=========================== */

.empty{

grid-column:1/-1;

background:white;

padding:80px;

border-radius:28px;

text-align:center;

font-size:26px;

font-weight:900;

color:#7586AA;

box-shadow:
0 14px 40px
rgba(
0,
0,
0,
.04
);

}



/* ===========================
   TABLET
=========================== */

@media(max-width:991px){

.department-grid{

grid-template-columns:
repeat(
2,
1fr
);

gap:22px;

}

.department-card{

min-height:320px;

}

.dept-name{

font-size:26px;

}

}



/* ===========================
   MOBILE
=========================== */

@media(max-width:768px){

.department-grid{

grid-template-columns:
1fr;

gap:18px;

margin-top:26px;

}

.department-card{

padding:22px;

min-height:auto;

border-radius:24px;

}

.dept-icon{

width:60px;

height:60px;

font-size:26px;

}

.dept-name{

font-size:22px;

margin-top:18px;

}

.dept-count{

font-size:15px;

}

.dept-desc{

font-size:14px;

line-height:1.7;

}

.dept-btn{

height:50px;

font-size:14px;

}

.empty{

padding:48px;

font-size:20px;

}

}

sp_widget.script:
(function(){
    data.departments = [];

    var dep = new GlideRecord('x_1902481_employ_0_department');
    dep.orderBy('department_name');
    dep.query();
    while(dep.next()){

        var deptName = dep.getValue('department_name') || 'Unnamed Department';
        var employeeCount = 0;

        // Count by department NAME since we store name directly now
        var emp = new GlideAggregate('x_1902481_employ_0_employee');
        emp.addQuery('department', deptName);
        emp.addAggregate('COUNT');
        emp.query();
        if(emp.next()){
            employeeCount = parseInt(emp.getAggregate('COUNT'), 10);
        }

        data.departments.push({
            sys_id: dep.getUniqueValue(),
            name: deptName,
            description: dep.getValue('description') || 'Department overview',
            employee_count: employeeCount
        });
    }
})();
